import json

# Build 30x30 grid with correct transformation
# Outer 5-border: rows 1-25, cols 1-25
# Interior: rows 2-24, cols 2-24 (23x23)

rect_top, rect_bottom = 1, 25
rect_left, rect_right = 1, 25

result = [[0]*30 for _ in range(30)]

# Copy 5-border
for r in range(rect_top, rect_bottom + 1):
    for c in range(rect_left, rect_right + 1):
        if r == rect_top or r == rect_bottom or c == rect_left or c == rect_right:
            result[r][c] = 5

# Fill interior: first/last row = all 2s, middle rows = 2 at edges, 5 in center
for r in range(rect_top + 1, rect_bottom):
    for c in range(rect_left + 1, rect_right):
        if r == rect_top + 1 or r == rect_bottom - 1:
            result[r][c] = 2
        elif c == rect_left + 1 or c == rect_right - 1:
            result[r][c] = 2
        else:
            result[r][c] = 5

print("Submitting:")
output_json = json.dumps({"action": "submit", "grid": result})
print(output_json)
